using System.Diagnostics;
using System.Drawing.Drawing2D;
using System.Text.Json;
using Microsoft.Win32;

namespace FortniteBoosterPRO;
internal sealed class GameItem { public string Name {get;set;}=""; public string Kind {get;set;}="game"; public string Exe {get;set;}=""; public string Cover {get;set;}=""; public bool Favorite {get;set;} }
internal static class Program { [STAThread] static void Main(){ ApplicationConfiguration.Initialize(); Application.Run(new MainForm()); } }
internal sealed class MainForm : Form {
 readonly Color bg=Color.FromArgb(18,19,23), card=Color.FromArgb(30,31,37), fg=Color.FromArgb(240,241,244), muted=Color.FromArgb(160,164,174), accent=Color.FromArgb(70,190,220);
 readonly string dir=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"FortniteBoosterPRO");
 string Db=>Path.Combine(dir,"library.json"); List<GameItem> items=new(); string tab="Игры", query=""; FlowLayoutPanel grid=null!; TextBox search=null!; Label count=null!;
 public MainForm(){Directory.CreateDirectory(dir); Text="Fortnite Booster PRO"; StartPosition=FormStartPosition.CenterScreen; ClientSize=new Size(1420,880); MinimumSize=new Size(1100,700); BackColor=bg; ForeColor=fg; Font=new Font("Segoe UI",10); LoadItems(); Build(); Render();}
 void LoadItems(){try{if(File.Exists(Db))items=JsonSerializer.Deserialize<List<GameItem>>(File.ReadAllText(Db))??new();}catch{} if(items.Count==0){items=new(){new(){Name="Fortnite",Favorite=true},new(){Name="Among Us"},new(){Name="Behind the Frame"},new(){Name="Death Stranding"},new(){Name="Fall Guys"},new(){Name="Farming Simulator 22"},new(){Name="Fortnite Battle Royale"},new(){Name="Fortnite Festival"},new(){Name="Genshin Impact"},new(){Name="Happy Game"},new(){Name="Insurmountable"},new(){Name="NBA 2K21"},new(){Name="Neon Abyss"},new(){Name="Supraland"},new(){Name="The Sims 4"},new(){Name="The Walking Dead"},new(){Name="XCOM 2"},new(){Name="Far Cry 3"}}; Save();}}
 void Save()=>File.WriteAllText(Db,JsonSerializer.Serialize(items,new JsonSerializerOptions{WriteIndented=true}));
 Button Btn(Control p,string t,int x,int y,int w,int h,Color b,Color f){var q=new Button{Text=t,Location=new(x,y),Size=new(w,h),BackColor=b,ForeColor=f,FlatStyle=FlatStyle.Flat,Font=new Font("Segoe UI",9,FontStyle.Bold),Cursor=Cursors.Hand};q.FlatAppearance.BorderSize=0;p.Controls.Add(q);return q;}
 void Build(){var top=new Panel{Dock=DockStyle.Top,Height=76,BackColor=bg};Controls.Add(top);top.Controls.Add(new Label{Text="FORTNITE BOOSTER",Location=new(24,20),Size=new(260,34),Font=new Font("Segoe UI",17,FontStyle.Bold),ForeColor=fg});
 var nav=new FlowLayoutPanel{Location=new(285,15),Size=new(520,48),BackColor=bg,WrapContents=false};foreach(var t in new[]{"Игры","Приложения и редакторы","Избранное","Коллекции"}){var b=Btn(nav,t,0,0, t.Length>12?178:105,42,bg, t==tab?fg:muted);b.Tag=t;b.Click+=(_,_)=>{tab=t;foreach(Button n in nav.Controls)n.ForeColor=(string)n.Tag! ==tab?fg:muted;Render();};}top.Controls.Add(nav);
 search=new TextBox{Location=new(820,20),Size=new(240,34),BackColor=card,ForeColor=fg,BorderStyle=BorderStyle.FixedSingle,PlaceholderText="⌕  Поиск в библиотеке"};search.TextChanged+=(_,_)=>{query=search.Text;Render();};top.Controls.Add(search);
 Btn(top,"+ Добавить игру",1075,18,145,38,card,fg).Click+=(_,_)=>AddItem();Btn(top,"BOOST",1230,18,90,38,accent,Color.Black).Click+=(_,_)=>Boost();
 Controls.Add(new Panel{Dock=DockStyle.Top,Height=1,BackColor=card});var body=new Panel{Dock=DockStyle.Fill,BackColor=bg,Padding=new Padding(26,16,26,20)};Controls.Add(body);body.BringToFront();top.BringToFront();
 body.Controls.Add(new Label{Text="Библиотека",Location=new(25,12),Size=new(400,36),Font=new Font("Segoe UI",20,FontStyle.Bold),ForeColor=fg});count=new Label{Location=new(27,53),Size=new(600,20),ForeColor=muted};body.Controls.Add(count);
 grid=new FlowLayoutPanel{Location=new(25,85),Size=new(body.Width-50,body.Height-105),Anchor=AnchorStyles.Top|AnchorStyles.Bottom|AnchorStyles.Left|AnchorStyles.Right,AutoScroll=true,WrapContents=true,BackColor=bg};body.Controls.Add(grid);}
 void Render(){if(grid==null)return;grid.SuspendLayout();grid.Controls.Clear();var list=items.Where(x=>(tab=="Игры"&&x.Kind=="game")||(tab=="Приложения и редакторы"&&x.Kind=="app")||((tab=="Избранное"||tab=="Коллекции")&&x.Favorite)).Where(x=>x.Name.Contains(query,StringComparison.OrdinalIgnoreCase)).ToList();count.Text=$"{list.Count} элементов • библиотека сохраняется автоматически";foreach(var g in list)grid.Controls.Add(Card(g));grid.ResumeLayout();}
 Control Card(GameItem g){var p=new Panel{Size=new(190,285),BackColor=card,Margin=new Padding(0,0,16,16),Cursor=Cursors.Hand};var art=new Panel{Location=new(0,0),Size=new(190,235),BackColor=Color.FromArgb(40+Math.Abs(g.Name.GetHashCode())%65,55+Math.Abs(g.Name.GetHashCode()/7)%75,75+Math.Abs(g.Name.GetHashCode()/13)%90)};art.Paint+=(_,e)=>{if(File.Exists(g.Cover)){try{using var im=Image.FromFile(g.Cover);e.Graphics.DrawImage(im,new Rectangle(0,0,190,235));return;}catch{}}using var f=new Font("Segoe UI",16,FontStyle.Bold);using var br=new SolidBrush(Color.White);var r=new RectangleF(10,60,170,110);e.Graphics.DrawString(g.Name.ToUpperInvariant(),f,br,r,new StringFormat{Alignment=StringAlignment.Center,LineAlignment=StringAlignment.Center});};p.Controls.Add(art);
 p.Controls.Add(new Label{Text=g.Name,Location=new(8,240),Size=new(174,22),ForeColor=fg,Font=new Font("Segoe UI",9,FontStyle.Bold),AutoEllipsis=true});p.Controls.Add(new Label{Text=string.IsNullOrEmpty(g.Exe)?"Добавить расположение":"Добавлено",Location=new(8,262),Size=new(170,17),ForeColor=muted,Font=new Font("Segoe UI",8)});
 var fav=Btn(p,g.Favorite?"♥":"♡",148,8,34,32,Color.FromArgb(175,10,10,15),Color.White);fav.Font=new Font("Segoe UI",14);fav.Click+=(_,_)=>{g.Favorite=!g.Favorite;Save();Render();};void open(object? s,EventArgs e)=>Launch(g);p.Click+=open;art.Click+=open;return p;}
 void AddItem(){using var d=new OpenFileDialog{Title="Выбери EXE игры или приложения",Filter="Программы (*.exe)|*.exe"};if(d.ShowDialog()!=DialogResult.OK)return;var g=new GameItem{Name=Path.GetFileNameWithoutExtension(d.FileName),Exe=d.FileName};var k=MessageBox.Show("Добавить как приложение? (Нет — игра)","Тип",MessageBoxButtons.YesNoCancel);if(k==DialogResult.Cancel)return;g.Kind=k==DialogResult.Yes?"app":"game";using var c=new OpenFileDialog{Title="Обложка (необязательно)",Filter="Изображения|*.png;*.jpg;*.jpeg;*.bmp"};if(c.ShowDialog()==DialogResult.OK){g.Cover=Path.Combine(dir,Guid.NewGuid()+Path.GetExtension(c.FileName));File.Copy(c.FileName,g.Cover);}items.Add(g);Save();Render();}
 void Launch(GameItem g){if(!File.Exists(g.Exe)){using var d=new OpenFileDialog{Title="Найди EXE для "+g.Name,Filter="Программы (*.exe)|*.exe"};if(d.ShowDialog()!=DialogResult.OK)return;g.Exe=d.FileName;Save();}try{Process.Start(new ProcessStartInfo(g.Exe){UseShellExecute=true,WorkingDirectory=Path.GetDirectoryName(g.Exe)!});}catch(Exception e){MessageBox.Show(e.Message);}}
 void Boost(){var f=new Form{Text="Fortnite Booster PRO — BOOST",Size=new(560,390),StartPosition=FormStartPosition.CenterParent,BackColor=bg,ForeColor=fg,FormBorderStyle=FormBorderStyle.FixedDialog,MaximizeBox=false};f.Controls.Add(new Label{Text="ПРОФИЛЬ СТАБИЛЬНОСТИ FPS",Location=new(22,20),Size=new(480,32),Font=new Font("Segoe UI",15,FontStyle.Bold)});f.Controls.Add(new Label{Text="Ryzen 7 5700X • RTX 4060 • 16 GB RAM • Windows 11",Location=new(24,60),Size=new(490,24),ForeColor=muted});f.Controls.Add(new Label{Text="Включает Game Mode и отключает фоновую запись Game DVR. Изменения применяются только для текущего пользователя Windows.",Location=new(24,100),Size=new(490,70)});var b=Btn(f,"ПРИМЕНИТЬ BOOST",24,190,490,48,accent,Color.Black);b.Click+=(_,_)=>{try{SetReg(@"Software\Microsoft\GameBar","AutoGameModeEnabled",1);SetReg(@"Software\Microsoft\GameBar","AllowAutoGameMode",1);SetReg(@"System\GameConfigStore","GameDVR_Enabled",0);SetReg(@"Software\Microsoft\Windows\CurrentVersion\GameDVR","AppCaptureEnabled",0);MessageBox.Show("Профиль применён. Перезагрузи ПК перед тестом Fortnite.");}catch(Exception ex){MessageBox.Show(ex.Message);}};f.Controls.Add(new Label{Text="Не отключает службы и не разгоняет комплектующие. Прирост FPS не гарантируется.",Location=new(24,260),Size=new(490,42),ForeColor=muted});f.ShowDialog(this);}
 void SetReg(string path,string name,int value){var backup=Path.Combine(dir,"registry-backup.json");Dictionary<string,JsonElement> old=new();if(File.Exists(backup))try{old=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(File.ReadAllText(backup))??new();}catch{}var id=path+"|"+name;if(!old.ContainsKey(id)){using var k=Registry.CurrentUser.OpenSubKey(path);bool exists=k?.GetValueNames().Contains(name)==true;old[id]=JsonSerializer.SerializeToElement(new{exists,value=exists?k!.GetValue(name):null});File.WriteAllText(backup,JsonSerializer.Serialize(old));}using var w=Registry.CurrentUser.CreateSubKey(path);w.SetValue(name,value,RegistryValueKind.DWord);}
}